  if (!variable(s.a) && !variable(s.b)) {
    if ((s.op === '/' || s.op === '%') && s.b === 0) return { changed: false, instruction: s };
    value = operation(s.op, s.a, s.b);
    if (value < -2147483648 || value > 2147483647) return { changed: false, instruction: s };
